// Detecte pays a partir du prefixe telephonique dans le nom de fichier.
function detectCountryFromName(name) {
  const n = String(name || '');
  if (/^00330|^0033\d/.test(n)) return { pays: 'FR', langue_appel: 'fr' };
  if (/^00440|^0044\d/.test(n)) return { pays: 'GB', langue_appel: 'en' };
  if (/^00490|^0049\d/.test(n)) return { pays: 'DE', langue_appel: 'de' };
  if (/^00480|^0048\d/.test(n)) return { pays: 'PL', langue_appel: 'pl' };
  if (/^00420|^0042\d/.test(n)) return { pays: 'CZ', langue_appel: 'cs' };
  return { pays: 'FR', langue_appel: 'fr' };
}

const items = $input.all();
const output = [];
for (const it of items) {
  const j = (it && it.json) || {};
  const file_id = j.id;
  const file_name = j.name || '';
  const mimeType = j.mimeType || '';
  if (!file_id) continue;
  if (mimeType === 'application/vnd.google-apps.folder') continue;
  if (mimeType === 'application/vnd.google-apps.shortcut') continue;

  const meta_url = 'https://sheets.googleapis.com/v4/spreadsheets/' + file_id + '?fields=' + encodeURIComponent('sheets.properties');
  const { pays, langue_appel } = detectCountryFromName(file_name);
  const phone = (file_name.match(/^(\d{8,15})_/) || [])[1] || '';

  output.push({ json: {
    file_id,
    file_name,
    mimeType,
    meta_url,
    pays,
    langue_appel,
    n_tel: phone,
    n_appel: file_name.replace(/\.(mp3\.csv|csv|mp3)$/i, ''),
  }});
}
return output;

const metaResponses = $input.all();
const loopItems = $('Loop Files (batch 5)').all();

const output = [];
for (let i = 0; i < metaResponses.length; i++) {
  const respJson = (metaResponses[i] && metaResponses[i].json) || {};
  const fileMeta = ((loopItems[i] && loopItems[i].json) || {});

  let sheetName = 'Sheet1';
  let lastCol = 'F';
  const sheets = respJson.sheets || [];
  if (sheets[0] && sheets[0].properties) {
    sheetName = sheets[0].properties.title || 'Sheet1';
    const colCount = (sheets[0].properties.gridProperties || {}).columnCount || 6;
    if (colCount && colCount <= 26) {
      lastCol = String.fromCharCode(64 + Math.min(Math.max(colCount, 6), 26));
    }
  }

  const range = encodeURIComponent(sheetName + '!A1:' + lastCol);
  const values_url = 'https://sheets.googleapis.com/v4/spreadsheets/' + fileMeta.file_id + '/values/' + range;

  output.push({ json: {
    ...fileMeta,
    sheet_name: sheetName,
    last_col: lastCol,
    values_url,
    meta_error: respJson.error ? (respJson.error.message || JSON.stringify(respJson.error)) : '',
  }});
}

return output;

// Build AFM-specific audit prompt. Detecte flow (cde_tel vs sav) puis applique la bonne grille.

function timeToSeconds(s) {
  if (s === undefined || s === null) return 0;
  const parts = String(s).trim().split(':').map((x) => Number(x));
  if (parts.some((p) => !Number.isFinite(p))) return 0;
  if (parts.length === 3) return parts[0]*3600 + parts[1]*60 + parts[2];
  if (parts.length === 2) return parts[0]*60 + parts[1];
  return parts[0] || 0;
}

function findHeader(headers, names) {
  for (const name of names) { const idx = headers.indexOf(name.toLowerCase()); if (idx >= 0) return idx; }
  for (const name of names) {
    const ln = name.toLowerCase();
    for (let i = 0; i < headers.length; i++) { if (headers[i].includes(ln)) return i; }
  }
  return -1;
}

function detectFlow(text) {
  const t = String(text || '').toLowerCase();
  const SAV_STRONG = /(remboursement|rembourser|annuler|reclamation|r[eé]clamation|j['ae]i pass[eé] (une )?commande|o[uù] est ma commande|suivi de ma commande|je n['ae]i pas re[cç]u|retour(ner)?|d[eé]fectueux|where is my order|i placed an?? order|refund|return my|complaint|wo ist meine bestellung|erstattung|reklamation|gdzie jest moje zam[oó]wienie|zwrot|kde je m[ée] objedn|reklamac)/;
  if (SAV_STRONG.test(t)) return 'sav';
  const CDE_STRONG = /(passer (une |la )?commande|je voudrais commander|c['e]?est pour passer|code avantage|place an?? order|want to order|m[oö]chte (eine )?bestell|bestellung aufgeben|z[lł]o[zż]y[cć] zam|chc[eę] zam[oó]wi|chci objednat|katalog)/;
  if (CDE_STRONG.test(t)) return 'cde_tel';
  return 'cde_tel';
}

function makePlaceholder(meta, reason) {
  return {
    ...meta,
    flow: 'cde_tel',
    duree_appel_secondes: 0,
    transcript_text: '',
    transcript_text_for_ai: '',
    llm_prompt: 'Reponds avec : {"flow":"cde_tel","metadata":{"agent":"","n_client":"","n_cde":"","type":"non auditable","demande_client":"non auditable"},"criteres":{},"SI_detectees":[],"totaux":{"note_totale_sur_10":null,"note_sur_100":null,"note_zero_par_SI":false},"commentaire_global":"Non auditable : ' + (reason || 'inconnu') + '","commentaire_traduit_fr":""}',
    _placeholder: true,
    _placeholder_reason: reason || 'unknown',
  };
}

const GRID_CDE_TEL = `15 CRITERES CDE TEL (AFM BQ_1) :
1_accueil (max 0.5) — "Atlas for Men, [prenom], bonjour" complet=0.5 / partiel=0.2 / non=0 / SI si incorrect
2_identification (max 1.0) — nom+adresse+complete fiche+confirme=1.0 / partiel=0.5 / SI si pas de fiche
3_climat (max 0.5) — ton cordial+empathie=0.5 / partiel=0.2 / non maitrise=0 / SI si incorrect tout au long
4_mise_en_attente (max 0.3) — annonce objet + remercie ≤1m30=0.3 / oubli=0 / NA si pas de mise en attente / SI si >3min
5_conclusion (max 0.5) — confirme total+paiement+livraison+suite=0.5 / oubli element=0.2 / aucune=0
6_prise_conges (max 0.5) — "Je vous remercie M/Mme [nom] ... bonne journee de la part d'Atlas for Men"=0.5 / non norme=0 / SI si incorrect
7_personnalisation (max 0.5) — nom client ≥3 fois=0.5 / 1 omission=0.25 / manque=0
8_pre_commande (max 0.5) — demande code avantage + propose=0.5 / non=0
9_commande (max 1.2) — refs+tailles+dispo+prix=1.2 / oubli un=0.6 / pas indispo=0
10_outils (max 0.3) — sait utiliser=0.3 / non=0
11_coord_bancaires (max 0.2) — desactive+reactive enreg=0.2 / partial=0.1 / non=0 / SI grave si pas de desactivation lors de CB
12_rebond_commercial (max 1.0) — 2 articles complementaires=1.0 / 1 seul=0.5 / non=0 / SI si aucune proposition possible
13_objection (max 1.0) — analyse+identifie+traite=1.0 / a travailler=0.5 / non=0 / NA si pas d'objection / SI si non traitee
14_ecoute_active (max 1.0) — laisse parler+acquiesce=1.0 / coupe parfois=0.5 / pas du tout=0
15_accompagnement (max 1.0) — adapte+rassure+pas a pas=1.0 / a travailler=0.5 / aucun=0`;

const GRID_SAV = `16 CRITERES SAV (AFM BQ_4) :
1_accueil (max 0.5) — norme=0.5 / partiel=0.2 / non=0 / SI si incorrect
2_identification (max 1.0) — nom+adresse+complete+confirme=1.0 / partiel=0.5 / SI si rien
3_mise_en_attente (max 0.3) — annonce+remercie ≤1m30=0.3 / oubli=0 / NA / SI si >3min
4_conclusion (max 0.5) — resume decisions+suite+valide=0.5 / fiabilisation peu claire=0.2 / aucune=0
5_prise_conges (max 0.5) — norme=0.5 / non norme=0.2 / non=0 / SI si incorrect
6_personnalisation (max 0.5) — nom ≥3 fois=0.5 / 1 omission=0.25 / manque=0
7_climat (max 1.0) — cordial+empathie+pro=1.0 / a travailler=0.5 / non maitrise=0 / SI si incorrect
8_maitrise_directivite (max 0.5) — directivite+rebond+gere reactions=0.5 / manque=0.2 / se laisse porter=0
9_decouverte_reformulation (max 1.0) — demande objet + REFORMULE obligatoire=1.0 / a travailler=0.5 / non=0 / SI si pas de reformulation
10_pertinence_reponse (max 1.5) — procedure+complet+personnalise=1.5 / incomplet=0.75 / non maitrise=0 / SI si pas de reponse ou info erronee
11_outils (max 0.5) — sait chercher=0.5 / non=0
12_codification (max 0.5) — qualifie appel + recolte avis=0.5 / motif faux=0.2 / non=0 (souvent non observable sur transcript, alors note=0 + justification "non observable")
13_delai_traitement (max 0.2) — communique delai si pas immediat=0.2 / NA si immediat / SI si delai errone ou non communique
14_experience_client (max 1.0) — accompagnement+rassure+climat=1.0 / a travailler=0.5 / absent=0
15_ecoute_empathie (max 0.5) — empathie+excuses+ecoute=0.5 / manque=0.25 / absent=0
16_enchantement (max 0.5) — bonus va au-dela demande=0.5 / NA si pas d'opportunite`;

const responses = $input.all();
const urlItems = $('Build Values URL').all();
const output = [];

for (let i = 0; i < responses.length; i++) {
  const respItem = responses[i] || {};
  const respJson = (respItem && respItem.json) || {};
  const meta = ((urlItems[i] && urlItems[i].json) || {});

  if (respJson.error) {
    output.push({ json: makePlaceholder(meta, 'sheets_api_error: ' + String(respJson.error.message || '').slice(0, 150)) });
    continue;
  }

  const values = respJson.values || [];
  if (values.length < 2) {
    output.push({ json: makePlaceholder(meta, 'too_few_rows (' + values.length + ')') });
    continue;
  }

  const headers = (values[0] || []).map((h) => String(h || '').replace(/^\uFEFF/, '').trim().toLowerCase());
  const idxSpeaker = findHeader(headers, ['speaker', 'orateur', 'locuteur', 'rečník', 'mowca']);
  const idxStart = findHeader(headers, ['start_time', 'start time', 'start', 'debut']);
  const idxEnd = findHeader(headers, ['end_time', 'end time', 'end', 'fin']);
  const idxText = findHeader(headers, ['text', 'texte', 'transcription', 'contenu', 'content']);

  if (idxText < 0) {
    output.push({ json: makePlaceholder(meta, 'no_text_column [' + headers.join(',') + ']') });
    continue;
  }

  const lines = [];
  let lastEnd = 0, firstStart = -1;
  for (let r = 1; r < values.length; r++) {
    const row = values[r] || [];
    const speaker = idxSpeaker >= 0 ? String(row[idxSpeaker] || '').trim() : '';
    const text = String(row[idxText] || '').trim();
    if (!text) continue;
    const startStr = idxStart >= 0 ? String(row[idxStart] || '') : '';
    const endStr = idxEnd >= 0 ? String(row[idxEnd] || '') : '';
    const startSec = parseFloat(startStr) || timeToSeconds(startStr);
    const endSec = parseFloat(endStr) || timeToSeconds(endStr);
    if (endSec > lastEnd) lastEnd = endSec;
    if (firstStart < 0 || startSec < firstStart) firstStart = startSec;
    const ts = startStr ? '[' + startStr + '] ' : '';
    lines.push(ts + (speaker ? speaker + ': ' : '') + text);
  }

  const transcript = lines.join('\n').replace(/\r/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (!transcript) {
    output.push({ json: makePlaceholder(meta, 'empty_transcript') });
    continue;
  }

  const flow = detectFlow(transcript);
  const duree = lastEnd > 0 ? Math.round(lastEnd - Math.max(firstStart, 0)) : 0;

  const MAX_CHARS = 8000;
  let chatForAi = transcript;
  if (transcript.length > MAX_CHARS) {
    chatForAi = transcript.slice(0, 5000) + '\n[... segment median tronque ...]\n' + transcript.slice(-2500);
  }

  const grid = flow === 'sav' ? GRID_SAV : GRID_CDE_TEL;
  const dmt = (Math.floor(duree / 60)).toString().padStart(2,'0') + ':' + (duree % 60).toString().padStart(2,'0');

  const context = `Tu es auditeur qualite IA pour Atlas For Men (vetements outdoor, clientele senior 60+).\nCde Tel = nouvelles commandes catalogue (code avantage, refs+tailles, rebond 2 articles, CB->desactiver enreg).\nSAV = ou est ma cde, remboursement, plainte, retour, modification (reformulation obligatoire, delai traitement, codification).\nNormes accueil "Atlas for Men, [prenom], bonjour" / conge "Je vous remercie M/Mme [nom] ... bonne journee de la part d'Atlas for Men".\nATTENTION : ASR transcrit souvent mal "Atlas for Men" (la plateforme, Atlas Women, etc) — flag "Possible erreur ASR" si suspect.`;

  const flowLabel = flow === 'sav' ? 'SAV' : 'Cde Tel';
  const llm_prompt = [
    context, '',
    `FLUX DETECTE : ${flowLabel}`,
    `PAYS : ${meta.pays} / LANGUE : ${meta.langue_appel} / DUREE : ${dmt} / FICHIER : ${meta.file_name}`,
    '', grid, '',
    'REGLES STRICTES :',
    '- Aucune supposition : si transcript ne montre pas un critere, il N EST PAS maitrise.',
    '- SI = preuve INCONTESTABLE obligatoire ; dans le doute -> "Non maitrise".',
    '- NA explicite si critere pas applicable.',
    '- Transcript-only : climat/empathie sur indices textuels.',
    '- Justifications en francais (meme pour appels EN/DE/PL/CZ).',
    '',
    'FORMAT SORTIE — JSON STRICT, RIEN D AUTRE :',
    '{',
    '  "flow": "cde_tel|sav",',
    '  "metadata": { "agent":"", "n_client":"", "n_cde":"", "type":"", "demande_client":"resume 1 phrase fr" },',
    '  "criteres": {',
    '    "<key>": { "notation":"Maitrise|A perfectionner|Non maitrise|SI|NA|Conforme|Non conforme", "note": <number|"NA">, "bareme": <max>, "justification":"1-2 phrases citant transcript", "timestamp_preuve":"hh:mm:ss" }',
    '  },',
    '  "SI_detectees": [ {"critere":"<key>","evidence_transcript":"[ts] texte","gravite":"haute|critique"} ],',
    '  "totaux": { "note_totale_sur_10": <num>, "note_sur_100": <num>, "note_zero_par_SI": <bool> },',
    '  "commentaire_global": "3-5 phrases fr",',
    '  "commentaire_traduit_fr": ""',
    '}',
    '',
    'TRANSCRIPT :', chatForAi,
  ].join('\n');

  output.push({ json: {
    ...meta,
    flow,
    duree_appel_secondes: duree,
    DMT_DMC: dmt,
    transcript_text: transcript,
    transcript_text_for_ai: chatForAi,
    llm_prompt,
    _placeholder: false,
  }});
}

return output;

// Parse JSON Claude et FLATTEN chaque critere en 3 champs : <key>_notation, <key>_note, <key>_bareme.

const CDE_TEL_KEYS = ['1_accueil','2_identification','3_climat','4_mise_en_attente','5_conclusion','6_prise_conges','7_personnalisation','8_pre_commande','9_commande','10_outils','11_coord_bancaires','12_rebond_commercial','13_objection','14_ecoute_active','15_accompagnement'];
const SAV_KEYS = ['1_accueil','2_identification','3_mise_en_attente','4_conclusion','5_prise_conges','6_personnalisation','7_climat','8_maitrise_directivite','9_decouverte_reformulation','10_pertinence_reponse','11_outils','12_codification','13_delai_traitement','14_experience_client','15_ecoute_empathie','16_enchantement'];

const pickFirstText = (...values) => { for (const v of values) { if (typeof v === 'string' && v.trim()) return v.trim(); } return ''; };
const getRawText = (json) => pickFirstText(json.text, json.output, json.response, json.answer, json.content, json.result, (json.message && json.message.content) || '');
const parseJsonBlock = (raw) => {
  if (!raw) return null;
  let t = String(raw).trim();
  if (t.startsWith('```')) t = t.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const f = t.indexOf('{'), l = t.lastIndexOf('}');
  if (f !== -1 && l > f) { try { return JSON.parse(t.slice(f, l+1)); } catch (e) {} }
  return null;
};

function flattenCriteres(criteres, keys) {
  const out = {};
  for (const key of keys) {
    const c = (criteres && criteres[key]) || {};
    out[key + '_notation'] = c.notation != null ? String(c.notation) : '';
    out[key + '_note'] = (c.note != null && c.note !== '') ? c.note : '';
    out[key + '_bareme'] = (c.bareme != null && c.bareme !== '') ? c.bareme : '';
    out[key + '_justification'] = c.justification != null ? String(c.justification) : '';
  }
  return out;
}

const responses = $input.all();
const bases = $('Build AFM Prompt (Cde Tel | SAV)').all();
const now = new Date().toISOString();
const output = [];

for (let idx = 0; idx < responses.length; idx++) {
  const responseItem = (responses[idx] && responses[idx].json) || {};
  const base = ((bases[idx] && bases[idx].json) || {});
  const flowFinal = base.flow || 'cde_tel';
  const keys = flowFinal === 'sav' ? SAV_KEYS : CDE_TEL_KEYS;

  if (base._placeholder) {
    const empty = flattenCriteres({}, keys);
    output.push({ json: {
      currentDate: now,
      pays: base.pays || '',
      langue_appel: base.langue_appel || '',
      flow: flowFinal,
      nom_fichier: base.file_name || '',
      n_appel: base.n_appel || '',
      agent: '',
      n_client: '',
      n_cde: '',
      n_tel: base.n_tel || '',
      DMT_DMC: '',
      type: 'non auditable',
      demande_client: 'Non auditable : ' + (base._placeholder_reason || ''),
      duree_appel_secondes: 0,
      ...empty,
      note_totale_sur_10: '',
      note_sur_100: '',
      note_zero_par_SI: false,
      SI_count: 0,
      SI_details: '',
      commentaire_global: 'Placeholder : ' + (base._placeholder_reason || ''),
      commentaire_traduit_fr: '',
      criteres_full_json: '',
      audit_version: 'n8n_claude_v2',
    }});
    continue;
  }

  const rawText = !responseItem.error ? getRawText(responseItem) : '';
  const parsed = parseJsonBlock(rawText) || {};
  const meta = parsed.metadata || {};
  const criteres = parsed.criteres || {};
  const SI = parsed.SI_detectees || [];
  const totaux = parsed.totaux || {};

  const flat = flattenCriteres(criteres, keys);
  const SI_details = (Array.isArray(SI) ? SI : []).map(s => (s.critere || '?') + ' (' + (s.gravite || '?') + '): ' + (s.evidence_transcript || '').slice(0, 80)).join(' || ');

  output.push({ json: {
    currentDate: now,
    pays: base.pays || '',
    langue_appel: base.langue_appel || '',
    flow: parsed.flow || flowFinal,
    nom_fichier: base.file_name || '',
    n_appel: base.n_appel || '',
    agent: meta.agent || '',
    n_client: meta.n_client || '',
    n_cde: meta.n_cde || '',
    n_tel: base.n_tel || '',
    DMT_DMC: base.DMT_DMC || '',
    type: meta.type || '',
    demande_client: meta.demande_client || '',
    duree_appel_secondes: base.duree_appel_secondes || 0,
    ...flat,
    note_totale_sur_10: totaux.note_totale_sur_10 != null ? totaux.note_totale_sur_10 : '',
    note_sur_100: totaux.note_sur_100 != null ? totaux.note_sur_100 : '',
    note_zero_par_SI: !!totaux.note_zero_par_SI,
    SI_count: (Array.isArray(SI) ? SI.length : 0),
    SI_details,
    commentaire_global: parsed.commentaire_global || '',
    commentaire_traduit_fr: parsed.commentaire_traduit_fr || '',
    criteres_full_json: JSON.stringify(criteres),
    audit_version: 'n8n_claude_v2',
  }});
}
return output;
